CREATE TABLE "user" (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, "emailVerified" boolean NOT NULL DEFAULT false, image text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE session (id text PRIMARY KEY, "expiresAt" timestamptz NOT NULL, token text NOT NULL UNIQUE, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now(), "ipAddress" text, "userAgent" text, "userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE);
CREATE INDEX session_user_idx ON session("userId");
CREATE TABLE account (id text PRIMARY KEY, "accountId" text NOT NULL, "providerId" text NOT NULL, "userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamptz, "refreshTokenExpiresAt" timestamptz, scope text, password text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE INDEX account_user_idx ON account("userId");
CREATE TABLE verification (id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, "expiresAt" timestamptz NOT NULL, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE cases (id text PRIMARY KEY, owner_id text NOT NULL REFERENCES "user"(id), merchant text NOT NULL, environment text NOT NULL CHECK(environment IN ('demo','sandbox')), invoice_id text NOT NULL, customer text NOT NULL, title text NOT NULL, kind text NOT NULL, state text NOT NULL DEFAULT 'NEW', provider_invoice jsonb NOT NULL, invoice jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_id,environment,merchant,invoice_id));
CREATE INDEX cases_owner_env_idx ON cases(owner_id,environment,merchant);
CREATE TABLE evidence (id text PRIMARY KEY, case_id text NOT NULL REFERENCES cases(id), label text NOT NULL, kind text NOT NULL CHECK(kind IN ('agreement','message','note')), version integer NOT NULL CHECK(version>0), hash text NOT NULL, body text NOT NULL CHECK(octet_length(body)<=64000), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX evidence_case_idx ON evidence(case_id);
CREATE TABLE snapshots (id text PRIMARY KEY, case_id text NOT NULL REFERENCES cases(id), fingerprint text NOT NULL, raw jsonb NOT NULL, projection jsonb NOT NULL, provenance text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX snapshots_case_idx ON snapshots(case_id,created_at);
CREATE TABLE investigations (id text PRIMARY KEY, case_id text NOT NULL REFERENCES cases(id), evidence_hash text NOT NULL, invoice_hash text NOT NULL, status text NOT NULL, provenance text NOT NULL, prompt_version text NOT NULL, model text, result jsonb, error text, usage jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX investigations_case_idx ON investigations(case_id,created_at);
CREATE TABLE proposals (id text PRIMARY KEY, case_id text NOT NULL REFERENCES cases(id), investigation_id text NOT NULL REFERENCES investigations(id), version integer NOT NULL CHECK(version>0), invoice_hash text NOT NULL, evidence_hash text NOT NULL, operation jsonb NOT NULL, explanation text NOT NULL, state text NOT NULL CHECK(state IN ('DRAFT','APPROVED','SUPERSEDED','STALE')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(case_id,version));
CREATE TABLE commands (id text PRIMARY KEY, proposal_id text NOT NULL UNIQUE REFERENCES proposals(id), case_id text NOT NULL REFERENCES cases(id), actor_id text NOT NULL REFERENCES "user"(id), merchant text NOT NULL, environment text NOT NULL, invoice_id text NOT NULL, operation jsonb NOT NULL, before_hash text NOT NULL, evidence_hash text NOT NULL, intended_after jsonb NOT NULL, state text NOT NULL CHECK(state IN ('QUEUED','RUNNING','SUCCEEDED','STALE','UNSUPPORTED','RETRYABLE_FAILURE','UNKNOWN_OUTCOME','MANUAL_REVIEW')), attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0), error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX command_one_active_invoice ON commands(merchant,environment,invoice_id) WHERE state IN ('QUEUED','RUNNING','RETRYABLE_FAILURE','UNKNOWN_OUTCOME');
CREATE TABLE audit (id text PRIMARY KEY, case_id text REFERENCES cases(id), actor_id text NOT NULL, event text NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_case_idx ON audit(case_id,created_at);
CREATE TABLE webhook_inbox (id text PRIMARY KEY, invoice_id text NOT NULL, merchant text NOT NULL, payload jsonb NOT NULL, processed boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customer_grants (id text PRIMARY KEY, token_hash text NOT NULL UNIQUE, case_id text NOT NULL REFERENCES cases(id), explanation text NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX grants_case_idx ON customer_grants(case_id);
CREATE TABLE customer_feedback (id text PRIMARY KEY, grant_id text NOT NULL REFERENCES customer_grants(id), message text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE dashboard_state (owner_id text PRIMARY KEY REFERENCES "user"(id), state jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rate_limits (key text PRIMARY KEY, count integer NOT NULL, resets_at timestamptz NOT NULL);
CREATE TABLE ai_budget (day date PRIMARY KEY, calls integer NOT NULL CHECK(calls>=0), tokens integer NOT NULL CHECK(tokens>=0));
